class ReserveStockConcurrencyIT {
  @Test
  void opposingLineOrdersDoNotDeadlock() throws Exception {
    seedInventory(List.of(5L, 9L), 10_000);
    var pool = Executors.newFixedThreadPool(16);
    var futures = IntStream.range(0, 400).mapToObj(i -> pool.submit(() ->
        stock.reserveStock(order(i % 2 == 0 ? List.of(5L, 9L) : List.of(9L, 5L))))).toList();
    for (var f : futures) f.get(30, SECONDS);
    assertThat(reserved(5L)).isEqualTo(400);
  }
